#!/usr/bin/env bash
# Question 7: Deployment ${Q7_APP} not running. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q7_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q7_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q7_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q7_APP}
  namespace: ${Q7_NS}
  labels: { app: ${Q7_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q7_APP} }
  template:
    metadata:
      labels: { app: ${Q7_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 100m, memory: 64Mi }
EOF
kubectl -n "${Q7_NS}" get deployment "${Q7_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q7.uid"
chmod 644 "/var/tmp/cka-q7.uid"

case "${Q7_FAULT}" in
  memory-hog)
    to_mi() {
      local q="$1"
      case "$q" in
        *Ki) echo $(( ${q%Ki} / 1024 )) ;;
        *Mi) echo "${q%Mi}" ;;
        *Gi) echo $(( ${q%Gi} * 1024 )) ;;
        *k) echo $(( ${q%k} * 1000 / 1048576 )) ;;
        *M) echo $(( ${q%M} * 1000000 / 1048576 )) ;;
        *G) echo $(( ${q%G} * 1000000000 / 1048576 )) ;;
        "") echo 0 ;;
        *) echo $(( q / 1048576 )) ;;
      esac
    }
    i=0
    for n in $(kubectl get nodes -l '!node-role.kubernetes.io/control-plane' -o jsonpath='{.items[*].metadata.name}'); do
      i=$((i + 1))
      alloc=$(to_mi "$(kubectl get node "$n" -o jsonpath='{.status.allocatable.memory}')")
      used=0
      for q in $(kubectl get pods -A --field-selector "spec.nodeName=$n,status.phase!=Succeeded,status.phase!=Failed" -o jsonpath='{range .items[*]}{range .spec.containers[*]}{.resources.requests.memory}{" "}{end}{end}'); do
        used=$((used + $(to_mi "$q")))
      done
      # Leaves 40Mi: less than one replica's 64Mi.
      hog=$((alloc - used - 40))
      (( hog > 64 )) || { echo "worker $n has too little memory left" >&2; exit 1; }
      kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"apps/v1","kind":"Deployment","metadata":{"name":"warmup-'"$i"'","labels":{"role":"cache"}},"spec":{"replicas":1,"selector":{"matchLabels":{"app":"warmup-'"$i"'"}},"template":{"metadata":{"labels":{"app":"warmup-'"$i"'","role":"cache"}},"spec":{"nodeSelector":{"kubernetes.io/hostname":"'"$n"'"},"containers":[{"name":"cache","image":"busybox:1.36","command":["sleep","infinity"],"resources":{"requests":{"cpu":"10m","memory":"'"$hog"'Mi"}}}]}}}}' >/dev/null
    done
    kubectl -n "${Q7_NS}" wait --for=condition=Available deployment -l role=cache --timeout=180s >/dev/null
    ;;
  agent-anti-affinity)
    kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"apps/v1","kind":"DaemonSet","metadata":{"name":"log-agent"},"spec":{"selector":{"matchLabels":{"app":"log-agent"}},"template":{"metadata":{"labels":{"app":"log-agent","tier":"infra"}},"spec":{"containers":[{"name":"agent","image":"busybox:1.36","command":["sleep","infinity"],"resources":{"requests":{"cpu":"10m","memory":"16Mi"}}}]}}}}' >/dev/null
    kubectl -n "${Q7_NS}" rollout status daemonset/log-agent --timeout=180s >/dev/null
    kubectl -n "${Q7_NS}" patch deployment "${Q7_APP}" -p '{"spec":{"template":{"spec":{"affinity":{"podAntiAffinity":{"requiredDuringSchedulingIgnoredDuringExecution":[{"labelSelector":{"matchLabels":{"tier":"infra"}},"topologyKey":"kubernetes.io/hostname"}]}}}}}}'
    ;;
  node-affinity)
    kubectl -n "${Q7_NS}" patch deployment "${Q7_APP}" -p '{"spec":{"template":{"spec":{"affinity":{"nodeAffinity":{"requiredDuringSchedulingIgnoredDuringExecution":{"nodeSelectorTerms":[{"matchExpressions":[{"key":"disktype","operator":"In","values":["ssd"]}]}]}}}}}}}'
    ;;
  priority-class)
    kubectl -n "${Q7_NS}" patch deployment "${Q7_APP}" -p '{"spec":{"template":{"spec":{"priorityClassName":"critical-batch"}}}}'
    ;;
  topology-spread-zone)
    kubectl -n "${Q7_NS}" patch deployment "${Q7_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/topologySpreadConstraints","value":[{"maxSkew":1,"topologyKey":"topology.kubernetes.io/zone","whenUnsatisfiable":"DoNotSchedule","labelSelector":{"matchLabels":{"app":"'"${Q7_APP}"'"}}}]}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q7_NS}" scale "deployment/${Q7_APP}" --replicas=2
notready=0
for _ in $(seq 1 8); do
  states="$(kubectl -n "${Q7_NS}" get pods -l "app=${Q7_APP}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "${Q7_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
[[ "$(kubectl -n "${Q7_NS}" get deployment "${Q7_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q7_APP} still runs 2 replicas" >&2; exit 1; }
